	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/object"
)

func main() {
	repo, err := git.PlainOpenWithOptions(".", &git.PlainOpenOptions{DetectDotGit: true})
	if err != nil {
		panic(err)
	}

	cpID, _ := id.NewCheckpointID("629ded414de3")
	metadataPath := cpID.Path() + "/" + paths.MetadataFileName
	fmt.Printf("Looking for: %s\n", metadataPath)

	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		fmt.Println("No ref:", err)
		os.Exit(1)
	}
	fmt.Printf("Branch ref: %s\n", ref.Hash())

	iter, err := repo.Log(&gogit.LogOptions{
		From:  ref.Hash(),
		Order: gogit.LogOrderCommitterTime,
	})
	if err != nil {
		panic(err)
	}
	defer iter.Close()

	count := 0
	var foundCommit *object.Commit
	var author string
	err = iter.ForEach(func(c *object.Commit) error {
		count++
		tree, treeErr := c.Tree()
		if treeErr != nil {
			return nil
		}
		_, fileErr := tree.File(metadataPath)
		if fileErr != nil {
			if foundCommit != nil {
				fmt.Printf("Stopped at commit #%d: %s %s (file absent)\n", count, c.Hash.String()[:7], c.Author.Name)
				fmt.Printf("Author result: %s\n", author)
				return fmt.Errorf("stop")
			}
			return nil
		}
		foundCommit = c
		author = fmt.Sprintf("%s <%s>", c.Author.Name, c.Author.Email)
		if count <= 5 || c.Author.Name == "Sven Pfleiderer" || c.Hash.String()[:7] == "9af9661" {
			fmt.Printf("  #%d: %s %s %s (file exists)\n", count, c.Hash.String()[:7], c.Committer.When.Format("2006-01-02 15:04:05 -0700"), c.Author.Name)
		}
		return nil
	})
	fmt.Printf("Total commits visited: %d\n", count)
	fmt.Printf("Final author: %s\n", author)
}
