func TestHandleLifecycleCompaction_PreservesTranscriptOffset(t *testing.T) {
	// Cannot use t.Parallel() because we use t.Chdir()
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

	// Initialize git repo with a commit (not empty)
	setupGitRepoWithCommit(t, tmpDir)
	paths.ClearWorktreeRootCache()

	// Create .entire directory structure
	if err := os.MkdirAll(paths.EntireDir, 0o755); err != nil {
		t.Fatalf("Failed to create .entire: %v", err)
	}

	// Create a transcript file
	transcriptPath := filepath.Join(tmpDir, "transcript.jsonl")
	transcriptContent := `{"type":"user","message":{"role":"user","content":"test prompt"}}` + "\n"
	if err := os.WriteFile(transcriptPath, []byte(transcriptContent), 0o644); err != nil {
		t.Fatalf("Failed to create transcript: %v", err)
	}

	sessionID := "compaction-test-session"

	// Create session state with non-zero transcript offset (set by prior condensation)
	sessionState := &strategy.SessionState{
		SessionID:                 sessionID,
		CheckpointTranscriptStart: 50,
	}
	if err := strategy.SaveSessionState(context.Background(), sessionState); err != nil {
		t.Fatalf("Failed to save session state: %v", err)
	}

	ag := newMockAgent()
	event := &agent.Event{
		Type:       agent.Compaction,
		SessionID:  sessionID,
		SessionRef: transcriptPath,
	}

	// Compaction should NOT reset the transcript offset.
	// Many agents (e.g., Gemini) fire pre-compress as a no-op after every tool call;
	// resetting the offset causes stale files to re-appear in carry-forward.
	err := handleLifecycleCompaction(context.Background(), ag, event)
	if err != nil {
		t.Logf("handleLifecycleCompaction returned error (expected in minimal test): %v", err)
	}

	// Verify CheckpointTranscriptStart was preserved (not reset to 0)
	loadedState, loadErr := strategy.LoadSessionState(context.Background(), sessionID)
	if loadErr != nil {
		t.Fatalf("Failed to load session state after compaction: %v", loadErr)
	}
	if loadedState == nil {
		t.Fatal("Session state is nil after compaction")
	}
	if loadedState.CheckpointTranscriptStart != 50 {
		t.Errorf("CheckpointTranscriptStart = %d, want 50 (compaction should preserve offset)",
			loadedState.CheckpointTranscriptStart)
	}
}

// --- handleLifecycleSessionEnd tests ---

func TestHandleLifecycleSessionEnd_EmptySessionID(t *testing.T) {
	t.Parallel()

	ag := newMockAgent()
	event := &agent.Event{
		Type:      agent.SessionEnd,
		SessionID: "", // Empty
	}

	// Empty session ID should return nil (no error, just no-op)
	err := handleLifecycleSessionEnd(context.Background(), ag, event)
	if err != nil {
		t.Errorf("expected no error for empty session ID on SessionEnd, got: %v", err)
	}
}

package cli

import (
	"context"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/strategy"

	"github.com/go-git/go-git/v5"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestMarkSessionEnded_SetsPhaseEnded verifies that markSessionEnded
// transitions the session phase to ENDED via the state machine.
func TestMarkSessionEnded_SetsPhaseEnded(t *testing.T) {
	dir := setupGitRepoForPhaseTest(t)
	t.Chdir(dir)

	// Create a session in ACTIVE phase
	state := &strategy.SessionState{
		SessionID:  "test-session-end-1",
		BaseCommit: "abc123",
		StartedAt:  time.Now(),
		Phase:      session.PhaseActive,
	}
	err := strategy.SaveSessionState(context.Background(), state)
	require.NoError(t, err)

	// Call markSessionEnded
	err = markSessionEnded(context.Background(), "test-session-end-1")
	require.NoError(t, err)

	// Verify phase is ENDED
	loaded, err := strategy.LoadSessionState(context.Background(), "test-session-end-1")
	require.NoError(t, err)
	require.NotNil(t, loaded)

	assert.Equal(t, session.PhaseEnded, loaded.Phase,
		"markSessionEnded should set phase to ENDED")
	require.NotNil(t, loaded.EndedAt,
		"markSessionEnded should set EndedAt")
	require.NotNil(t, loaded.LastInteractionTime,
		"markSessionEnded should set LastInteractionTime")
}

// TestMarkSessionEnded_IdleToEnded verifies IDLE → ENDED transition.
func TestMarkSessionEnded_IdleToEnded(t *testing.T) {
	dir := setupGitRepoForPhaseTest(t)
	t.Chdir(dir)

	state := &strategy.SessionState{
		SessionID:  "test-session-end-idle",
		BaseCommit: "abc123",
		StartedAt:  time.Now(),
		Phase:      session.PhaseIdle,
	}
	err := strategy.SaveSessionState(context.Background(), state)
	require.NoError(t, err)

	err = markSessionEnded(context.Background(), "test-session-end-idle")
	require.NoError(t, err)

	loaded, err := strategy.LoadSessionState(context.Background(), "test-session-end-idle")
	require.NoError(t, err)
	assert.Equal(t, session.PhaseEnded, loaded.Phase)
	require.NotNil(t, loaded.EndedAt)
}

// TestMarkSessionEnded_AlreadyEndedIsNoop verifies ENDED → ENDED (no-op).
func TestMarkSessionEnded_AlreadyEndedIsNoop(t *testing.T) {
	dir := setupGitRepoForPhaseTest(t)
	t.Chdir(dir)

	originalEndedAt := time.Now().Add(-time.Hour)
	state := &strategy.SessionState{
		SessionID:  "test-session-end-noop",
		BaseCommit: "abc123",
		StartedAt:  time.Now(),
		Phase:      session.PhaseEnded,
		EndedAt:    &originalEndedAt,
	}
	err := strategy.SaveSessionState(context.Background(), state)
	require.NoError(t, err)

	err = markSessionEnded(context.Background(), "test-session-end-noop")
	require.NoError(t, err)

	loaded, err := strategy.LoadSessionState(context.Background(), "test-session-end-noop")
	require.NoError(t, err)
	assert.Equal(t, session.PhaseEnded, loaded.Phase)
	// EndedAt should still be set (updated, not cleared)
	require.NotNil(t, loaded.EndedAt)
}

// TestMarkSessionEnded_EmptyPhaseBackwardCompat verifies that sessions
// without a Phase field get properly transitioned.
func TestMarkSessionEnded_EmptyPhaseBackwardCompat(t *testing.T) {
	dir := setupGitRepoForPhaseTest(t)
	t.Chdir(dir)

	state := &strategy.SessionState{
		SessionID:  "test-session-end-compat",
		BaseCommit: "abc123",
		StartedAt:  time.Now(),
		Phase:      "", // pre-state-machine
	}
	err := strategy.SaveSessionState(context.Background(), state)
	require.NoError(t, err)

	err = markSessionEnded(context.Background(), "test-session-end-compat")
	require.NoError(t, err)

	loaded, err := strategy.LoadSessionState(context.Background(), "test-session-end-compat")
	require.NoError(t, err)
	assert.Equal(t, session.PhaseEnded, loaded.Phase,
		"empty phase → IDLE → ENDED")
}

// TestMarkSessionEnded_NoState verifies that markSessionEnded is a no-op
// when no session state exists.
func TestMarkSessionEnded_NoState(t *testing.T) {
	dir := setupGitRepoForPhaseTest(t)
	t.Chdir(dir)

	err := markSessionEnded(context.Background(), "nonexistent-session")
	assert.NoError(t, err, "should be a no-op when no state exists")
}

// setupGitRepoForPhaseTest creates a temp directory with an initialized git repo.
func setupGitRepoForPhaseTest(t *testing.T) string {
	t.Helper()

	dir := t.TempDir()
	_, err := git.PlainInit(dir, false)
	require.NoError(t, err)
	return dir
}

func TestDispatchLifecycleEvent_RoutesToCorrectHandler(t *testing.T) {
	t.Parallel()

	// Test that each event type is routed (we can't easily verify which handler
	// was called without dependency injection, but we can verify no panic and
	// expected error types for each event type with minimal required data)

	testCases := []struct {
		name        string
		eventType   agent.EventType
		sessionID   string
		expectError bool
		errorSubstr string
	}{
		{
			name:        "SessionStart with empty session ID",
			eventType:   agent.SessionStart,
			sessionID:   "",
			expectError: true,
			errorSubstr: "no session_id",
		},
		{
			name:        "TurnStart with empty session ID",
			eventType:   agent.TurnStart,
			sessionID:   "",
			expectError: true,
			errorSubstr: "no session_id",
		},
		{
			name:        "TurnEnd with empty transcript",
			eventType:   agent.TurnEnd,
			sessionID:   "test",
			expectError: true,
			errorSubstr: "transcript file not specified",
		},
		{
			name:        "Compaction with empty transcript is no-op",
			eventType:   agent.Compaction,
			sessionID:   "test",
			expectError: false, // Compaction just resets offset; doesn't read transcript
		},
		{
			name:        "SessionEnd with empty session ID is no-op",
			eventType:   agent.SessionEnd,
			sessionID:   "",
			expectError: false,
		},
		{
			name:        "SubagentStart with valid data",
			eventType:   agent.SubagentStart,
			sessionID:   "test",
			expectError: true, // Will fail due to CapturePreTaskState needing git repo
			errorSubstr: "failed to capture pre-task state",
		},
		{
			name:        "SubagentEnd with valid data",
			eventType:   agent.SubagentEnd,
			sessionID:   "test",
			expectError: false, // Succeeds when run from a valid git repo
