342→	sessionID := "compaction-test-session"
343→
344→	// Create session state with non-zero transcript offset (set by prior condensation)
345→	sessionState := &strategy.SessionState{
346→		SessionID:                 sessionID,
347→		CheckpointTranscriptStart: 50,
348→	}
