361→	// Many agents (e.g., Gemini) fire pre-compress as a no-op after every tool call;
362→	// resetting the offset causes stale files to re-appear in carry-forward.
363→	err := handleLifecycleCompaction(context.Background(), ag, event)
364→	if err != nil {
