441→func TestDispatchLifecycleEvent_RoutesToCorrectHandler(t *testing.T) {
442→	t.Parallel()
443→
444→	// Test that each event type is routed (we can't easily verify which handler
445→	// was called without dependency injection, but we can verify no panic and
446→	// expected error types for each event type with minimal required data)
447→
448→	testCases := []struct {
449→		name        string
450→		eventType   agent.EventType
451→		sessionID   string
452→		expectError bool
453→		errorSubstr string
454→	}{
455→		{
456→			name:        "SessionStart with empty session ID",
457→			eventType:   agent.SessionStart,
458→			sessionID:   "",
459→			expectError: true,
460→			errorSubstr: "no session_id",
461→		},
462→		{
463→			name:        "TurnStart with empty session ID",
464→			eventType:   agent.TurnStart,
465→			sessionID:   "",
466→			expectError: true,
467→			errorSubstr: "no session_id",
468→		},
469→		{
470→			name:        "TurnEnd with empty transcript",
471→			eventType:   agent.TurnEnd,
472→			sessionID:   "test",
473→			expectError: true,
474→			errorSubstr: "transcript file not specified",
475→		},
476→		{
477→			name:        "Compaction with empty transcript is no-op",
478→			eventType:   agent.Compaction,
479→			sessionID:   "test",
480→			expectError: false, // Compaction just resets offset; doesn't read transcript
481→		},
482→		{
483→			name:        "SessionEnd with empty session ID is no-op",
484→			eventType:   agent.SessionEnd,
485→			sessionID:   "",
486→			expectError: false,
487→		},
488→		{
489→			name:        "SubagentStart with valid data",
490→			eventType:   agent.SubagentStart,
491→			sessionID:   "test",
492→			expectError: true, // Will fail due to CapturePreTaskState needing git repo
493→			errorSubstr: "failed to capture pre-task state",
494→		},
495→		{
496→			name:        "SubagentEnd with valid data",
497→			eventType:   agent.SubagentEnd,
498→			sessionID:   "test",
499→			expectError: false, // Succeeds when run from a valid git repo
500→		},
501→	}
502→
503→	for _, tc := range testCases {
504→		t.Run(tc.name, func(t *testing.T) {
505→			t.Parallel()
