519→				} else if !strings.Contains(err.Error(), tc.errorSubstr) {
520→					t.Errorf("expected error containing %q, got: %v", tc.errorSubstr, err)
521→				}
522→			} else {
523→				if err != nil {
524→					t.Errorf("expected no error, got: %v", err)
525→				}
526→			}
527→		})
528→	}
529→}
