 17→func TestIsShadowBranch(t *testing.T) {
 18→	tests := []struct {
 19→		name       string
 20→		branchName string
 21→		want       bool
 22→	}{
 23→		// Valid shadow branches - old format (7+ hex chars)
 24→		{"old format: 7 hex chars", "entire/abc1234", true},
 25→		{"old format: 7 hex chars numeric", "entire/1234567", true},
 26→		{"old format: full commit hash", "entire/abcdef0123456789abcdef0123456789abcdef01", true},
 27→		{"old format: mixed case hex", "entire/AbCdEf1", true},
 28→
 29→		// Valid shadow branches - new format with worktree hash (7 hex + dash + 6 hex)
 30→		{"new format: standard", "entire/abc1234-e3b0c4", true},
 31→		{"new format: numeric worktree hash", "entire/1234567-123456", true},
 32→		{"new format: full commit with worktree", "entire/abcdef0123456789-fedcba", true},
 33→		{"new format: mixed case", "entire/AbCdEf1-AbCdEf", true},
 34→
 35→		// Invalid patterns
 36→		{"empty after prefix", "entire/", false},
 37→		{"too short commit (6 chars)", "entire/abc123", false},
 38→		{"too short commit (1 char)", "entire/a", false},
 39→		{"non-hex chars in commit", "entire/ghijklm", false},
 40→		{"sessions branch", paths.MetadataBranchName, false},
 41→		{"no prefix", "abc1234", false},
 42→		{"wrong prefix", "feature/abc1234", false},
 43→		{"main branch", "main", false},
 44→		{"master branch", "master", false},
 45→		{"empty string", "", false},
 46→		{"just entire", "entire", false},
 47→		{"entire with slash only", "entire/", false},
 48→		{"worktree hash too short (5 chars)", "entire/abc1234-e3b0c", false},
 49→		{"worktree hash too long (7 chars)", "entire/abc1234-e3b0c44", false},
 50→		{"non-hex in worktree hash", "entire/abc1234-ghijkl", false},
 51→		{"missing commit hash", "entire/-e3b0c4", false},
 52→	}
 53→
 54→	for _, tt := range tests {
